import{_ as t,c as o,o as e,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"2、【坤】 坤下坤上","description":"周易尚氏學 - 2、【坤】 坤下坤上","frontmatter":{"title":"2、【坤】 坤下坤上","description":"周易尚氏學 - 2、【坤】 坤下坤上"},"headers":[],"relativePath":"classics/shangshi/007.md","filePath":"classics/shangshi/007.md"}'),p={name:"classics/shangshi/007.md"};function u(h,a,i,q,l,n){return e(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="_2、【坤】-坤下坤上" tabindex="-1">2、【坤】 坤下坤上 <a class="header-anchor" href="#_2、【坤】-坤下坤上" aria-label="Permalink to “2、【坤】 坤下坤上”">​</a></h1><p>元亨。謂二五也。乾元亨二五獨吉。坤亦然。元亨並無陰陽之分。虞仲翔謂坤含光大。凝乾之元。終於坤亥。出乾初子。故元亨。案彖傳曰。至哉坤元。是坤亦言元。不專屬乾。坤六五雲。黃裳元吉。是其證。乾為馬。坤為牝。貞卜問也。利牝馬之貞。即利牝馬之佔也。牝馬柔順。言陰必順陽也。君子有攸往。言具坤德之君子。有所行也。惠棟端木國湖泥於坤為小人之象。謂君子指陽非也。地道無成。故不可先。先則迷而失道。惟隨陽之後。以陽為主。則靡不利也。西南得朋。東北喪朋。舊解以朋字類字失詁。故鮮得解者。馬融荀爽以陰遇陰為朋。虞翻謂失之甚矣。乃用參同契。月三日出庚。震象。八日見丁方。兌象。兌二陽為朋。庚西丁南。故曰西南得朋。三十日坤象。月滅乙癸。癸北乙東。故曰東北喪朋。苦心搜索以求朋象。豈知兌之為朋。以陰遇陽。非以二陽。陽遇陽同人謂之敵剛。陰遇陰中孚謂之得敵。然則虞說與馬荀背易理等耳。然支離穿鑿。則過於馬荀矣。復曰朋來無咎。蹇九五曰。大蹇朋來。解九四曰朋至斯孚。皆以陰得陽為朋。而坤逆行。消息卦自西而南陽日增。自東而北陽遞減。增則得朋。減則喪朋。而坤道無成。故安靜貞定則吉也。</p><p>彖曰。至哉坤元。萬物資生。乃順承天。坤厚載物。德合無疆。含弘光大。品物咸亨。牝馬地類。行地無疆。柔順利貞。君子攸行。先迷失道。後順得常。西南得朋。乃與類行。東北喪朋。乃終有慶。安貞之吉。應地無疆。</p><p>何休公羊傳元年注云。元者氣也。萬物資坤元以生。坤元實順天以行。故天道廣大無疆。惟坤之德能合之也。萬物皆孕毓於地。故曰含弘。萬物皆成長於地。故曰光大。光大則咸亨矣。</p><p>陰陽合為類。乾為馬。故馬與地類。而牝馬尤與地類。君子攸行者。謂柔順利貞之德。為君子所法也。九家謂乾來據坤。為君子攸行。失傳旨。</p><p>夫曰行曰終。乃自西而南。自東而北而逆行也。非以西南東北相對待也。明矣。消息卦自西而南陽日增。故曰西南得朋。陰以陽為類。故曰乃與類行。消息卦自東而北陽遞減。故曰東北喪朋。夫事有終必有始。喪朋之地始於巳。終於亥。坤行至亥。陽喪盡而為純坤。乃反曰有慶者何也。則以周易之位。乾原居亥。純坤與純乾相遇。天地合德。萬物由此出生。故曰有慶。易凡言有慶者。皆謂陰遇陽。大畜晉睽六五。皆上承陽。故皆曰往有慶。易林中孚之坤雲。符左契右。相與合齒。乾坤利貞。乳生六子。太玄玄文雲。入冥出冥。新故代更。皆說有慶之故也。後儒皆承用虞氏解。謂坤行至西南。月又將生明為有慶。是不知終為何處也。終者艮象亥方。周禮宰夫。及大司徒歲終注。皆日周季冬也。周季冬為亥月。又爾雅釋天雲。月在壬曰終。壬亦亥方。是終指亥方甚明。說卦雲。艮成終。終於亥也。故夫洞明易理者。莫過於焦延壽與楊子云也。(焦氏易詁。有詳說。可參閱。)</p><p>坤道主靜。故曰安。易林雲。乾坤利貞。乳生六子。安貞即利貞。利貞即天地合德。合則相感。故曰應地無疆。</p><p>象日。地勢坤。君子以厚德載物。</p><p>王弼曰。地形不順其勢順。是王弼之本。作地勢順也。來衷曰。地有上下九等之差。故以形勢言其性。夫曰性則亦讀為順也。而皆未引說卦坤順為詁。是愈證宋王本之皆作地勢順。故不引說卦為證。蓋坤古文作&quot;巛&quot;。而&quot;巛&quot;為順之叚字。故宋王皆讀&quot;巛&quot;為順。自正義改作坤。而順字遂無由識。至清儒王引之等。據說卦乾健坤順之文。謂天行健。即天行乾。地勢順即地勢坤。夫乾坤之為天地。不惟說卦言之。彖象傳並言之。故以天代乾。以地代坤。今不從宋王注。以坤為順之訛字。(若作&quot;巛&quot;則不訛)謂天行健即天行乾。地勢順即地勢坤。是天行天地勢地也。尚可通乎。王又謂&quot;巛&quot;即川字。川與坤順聲近。故借川作坤。是尤不安。夫坤古作&quot;巛&quot;。是古文作&quot;巛&quot;也。隸書原以變古文之繁重。若&quot;巛&quot;字本即簡易。故隸書常因而不改。大戴禮保傅篇。易之乾&quot;巛&quot;。家語執轡篇。此乾&quot;巛&quot;之美。後漢輿服志。堯舜垂裳。蓋取諸乾&quot;巛&quot;。北史太和三年。&quot;巛&quot;德六合殿成。又坤字之見於漢碑者。無不作&quot;巛&quot;。再徵之金文。周師訇敦銘雲。用作&quot;巛&quot;宮寶。王陶廬雲。&quot;巛&quot;即坤字。由此證&quot;巛&quot;即坤。非有所借也明矣。引之謂順因川而得聲。愚以為順因&quot;巛&quot;而得聲。推之訓馴巡紃等字皆然。引之蓋泥於說文坤下無重&quot;巛&quot;之文。謂&quot;巛&quot;非坤本字。王陶廬雲。玉篇&quot;巛&quot;下注曰古文坤字。廣韻亦曰古文以坤為&quot;巛&quot;。二書皆胚胎於說文。據此說文必有&quot;巛&quot;字。後奪之耳。不然二書不敢臆造。又云釋文原雲。&quot;巛&quot;本又作坤。坤今字。今改為坤本又作&quot;巛&quot;。&quot;巛&quot;今字。文理謬戾已極。是皆因孔氏改&quot;巛&quot;作坤。後人遂並釋文而亦改矣。按王說是也。詩周頌有夷之行。釋文雲。&quot;巛&quot;苦魂反。字亦作坤。此處釋文應同。然則坤本作&quot;巛&quot;。徵之金石傳記無不然。漢本易之作地勢順。徵之宋注王注亦無不然。然今本易何以訛作地勢坤。則以漢本易。坤原作&quot;巛&quot;。乃借&quot;巛&quot;為順也。何言之。順既因&quot;巛&quot;而得聲。在古文例常叚借。如大壯卦以易為場，夬以次且為趑趄。小畜以血為恤。皆因其得聲之字而叚借。今以&quot;巛&quot;叚順。正其例耳。孔氏知&quot;巛&quot;即坤。不知&quot;巛&quot;為順之叚字。遂竟改作坤矣。若宋王則皆讀作順也。以宋王本皆作&quot;巛&quot;也。作&quot;巛&quot;則人易知為順矣。其以說卦為解者。於字之沿革。盡失其義。厚德載物者坤。君子取以為法。虞仲翔必謂君子為乾亦非。又易以&quot;巛&quot;為大川。焦氏易林以&quot;巛&quot;為水。為江河淮濟。九家注蠱亦以坤地為水。邵子坤水之象之所本也。蓋&quot;巛&quot;即川字即水字。故易林復以坎為土。邵子複本之。疑古以水土為一物。能合而不能分。比曰地上有水。師曰地中有水。證以古文。稽之卦象。而益信矣。</p><p>(金文水作氺。兩旁畫不連。劉澗琴雲。效鼎涉作氺。殷契衍作氺。囦作氺。又永字從水。而金文作氺。是皆水字兩旁畫皆不斷。可證&quot;巛&quot;川水三字。古文皆同。)</p><p>初六。履霜。堅冰至。</p><p>陽進陰退。陽順陰逆。故陽自七進九為老陽。陰自八退六為老陰。陰極則變。故易用六也。於卦為姤。時當夏至。一陰初生。初震爻故曰履。陰微故以霜為喻。乾為冰為堅。坤行至上當亥方。與乾相遇。故曰堅冰。言五月微陰初見。馴至亥月而極寒。必然之勢。當憬然悟也。乾寶以五月無霜。謂陰氣既動。則必至於履霜。必至於堅冰者非也。霜即喻此微陰。微陰見故曰履霜。非有待於後也。其待者乃堅冰也。</p><h3 id="象日。履霜。陰始凝也。" tabindex="-1">象日。履霜。陰始凝也。 <a class="header-anchor" href="#象日。履霜。陰始凝也。" aria-label="Permalink to “象日。履霜。陰始凝也。”">​</a></h3><p>(依郭京讀)馴至其道。至堅冰也。乾為堅冰。言陰生於午。至亥純坤與純乾相遇。故曰至。</p><p>六二。直方大。不習無不利。</p><p>二為坤本位。坤二之利。與乾五之利同也。後人泥於乾動為直。及小往大來之文。必以直大屬之乾。於是經義遂迂曲而不得解。豈知直方大皆謂坤。彖傳文言所釋至明。文言云。直其正也。正謂二。二得位中正。故曰直。彖傳雲。含弘光大。大謂坤。坤萬物資生。焉得不大。蓋方者地之體。大者地之用。而二又居中直之位。故曰直方大。後儒見象傳未言大。便疑大為衍文。然陸德明時。漢魏六朝本具在。從無謂大字衍者。況文言引亦有大字乎。陰消至二遁。前承重陽。得主有利。故不習無不利。文言釋曰。不疑其所行。正謂二承陽也。</p><h3 id="象日。六二之動。直以方也。不習無不利。地道光也。" tabindex="-1">象日。六二之動。直以方也。不習無不利。地道光也。 <a class="header-anchor" href="#象日。六二之動。直以方也。不習無不利。地道光也。" aria-label="Permalink to “象日。六二之動。直以方也。不習無不利。地道光也。”">​</a></h3><p>六二與九五相上下。故曰動。陰順陽。故曰地道光。</p><p>六三。含章可貞。或從王事。無成。有終。</p><p>坤為文。故曰章。坤閉故曰含章。陰消至三否。正君子儉德避難之時。故雖有文章。含而不露。貞靜自守。荀虞謂三陽位。以陰據其上。故曰含章。後儒多從之。非也。文言釋章為美。仍坤象。非謂陽位也。否上乾為王。三承重陽。故曰從王事。三不當位故或之。與或躍在淵義同。言慎審也。陰順陽。故無敢成。成法也。式也。言不敢作法也。陰始姤。代乾終事。故曰有終。○按純坤無乾。王事之象何來乎。須知乾息從復始。坤消從姤始。故復姤亦為小父母。坤消至三。上乾如故也。故曰從王事。彼夫訟三曰從王事。履三曰武人為於大君。皆以上承陽。茲與之同。觀初爻曰。履霜堅冰至。言陽將以次消也。故卦雖無乾。爻辭皆視乾而系也。先儒坐不明此理。又鮮能以易解易。故說王事皆無著。</p><h3 id="象日。含章可貞。以時發也。或從王事。知光大也。" tabindex="-1">象日。含章可貞。以時發也。或從王事。知光大也。 <a class="header-anchor" href="#象日。含章可貞。以時發也。或從王事。知光大也。" aria-label="Permalink to “象日。含章可貞。以時發也。或從王事。知光大也。”">​</a></h3><p>時不可。故俟時而發。或從王事。知時至矣。故曰光大。</p><p>六四。括囊。無咎無譽。</p><p>坤為囊。楊子方言。括關閉也。坤閉故曰括囊。陰消至四八月觀。天地將閉塞矣。陰在三否。陰陽平均。故或從王事。至四則陰盛陽衰。時不可矣。故括囊。言無所表著也。無與於世。故無咎譽。</p><h3 id="象日。括囊無咎。慎不害也。" tabindex="-1">象日。括囊無咎。慎不害也。 <a class="header-anchor" href="#象日。括囊無咎。慎不害也。" aria-label="Permalink to “象日。括囊無咎。慎不害也。”">​</a></h3><p>慎故無咎。不害即無咎也。</p><p>六五。黃裳元吉。</p><p>坤為裳。色黃。故曰黃裳。坤為下。裳得下飾。五位正中。黃者中色。故曰黃裳元吉。元者善之長。五位極尊。故曰元。元謂五。大有鼎皆曰元吉。皆謂六五。毛奇齡謂五降二承乾為元吉。以元專屬乾。非也。</p><h3 id="象曰。黃裳元吉。文在中也。" tabindex="-1">象曰。黃裳元吉。文在中也。 <a class="header-anchor" href="#象曰。黃裳元吉。文在中也。" aria-label="Permalink to “象曰。黃裳元吉。文在中也。”">​</a></h3><p>坤為文。黃裳文飾。言所以吉者。以居中位也。</p><p>上六。龍戰於野。其血玄黃。</p><p>陰至上六。坤德全矣。故萬物由以出生。然孤陰不能生也。荀爽雲。消息之位。坤在於亥。下有伏乾。陰陽相和。故曰龍戰於野。坤為野。龍者陽。說文壬下雲。易曰龍戰於野。戰者接也。乾鑿度雲。乾坤合氣戌亥。合氣即接。九家雲。玄黃天地之雜。言乾坤合居。夫曰相和。曰合氣。曰合居。則戰之為和合明矣。皆與許詁同也。而萬物出生之本由於血。血者天地所遺氤氳之氣。天玄地黃。其血玄黃者。言此血為天地所和合。故能生萬物也。易林說此雲。(中孚之坤)符左契右。相與合齒。乾坤利貞。乳生六子。夫曰符契。曰合齒。則乾坤接也。即龍戰於野也。消息卦。坤亥下即震子出。故曰乳生六子。彖傳雲。乃終有慶。慶此也。惟荀與九家。皆以血為陰。仍違易旨。易明言天地雜。則血非純陰可知。純陰則離其類矣。胡能生物。至侯果謂陰盛似陽。王弼乾寶謂陰盛逼陽。陽不堪故戰。以戰為戰爭。後孔穎達朱子。因經言戰又言血。疑陰陽兩傷者。皆夢囈語也。清儒獨惠士奇用許說謂戰者接也。陰陽交接。卦無傷象。識過前人遠矣。</p><h3 id="象日。龍戰於野。其道窮也。陰至上六而極。故曰窮。窮盡也。" tabindex="-1">象日。龍戰於野。其道窮也。陰至上六而極。故曰窮。窮盡也。 <a class="header-anchor" href="#象日。龍戰於野。其道窮也。陰至上六而極。故曰窮。窮盡也。" aria-label="Permalink to “象日。龍戰於野。其道窮也。陰至上六而極。故曰窮。窮盡也。”">​</a></h3><p>用六。利永貞。</p><p>此亦明筮例也。八六皆陰。今遇陰。胡以只言六不言八。則以六為用而變七也。利永貞。申用六之故也。六何以必變。六為老陰。陰極不返。則太柔矣。又言曰。貞固足以乾事。永貞則健而陽矣。故象曰以大終。大者陽。言陰極則變陽也。</p><h3 id="象曰。用六永貞。以大終也。" tabindex="-1">象曰。用六永貞。以大終也。 <a class="header-anchor" href="#象曰。用六永貞。以大終也。" aria-label="Permalink to “象曰。用六永貞。以大終也。”">​</a></h3><p>陽大陰小。以大終者。言陰極必返陽也。舊解因不知用六義意。故說大終。無有當者。</p><p>文言</p><h3 id="坤至柔而動也剛。至靜而德方。後得主而有常。含萬物而化光。坤道其順乎。承天而時行。" tabindex="-1">坤至柔而動也剛。至靜而德方。後得主而有常。含萬物而化光。坤道其順乎。承天而時行。 <a class="header-anchor" href="#坤至柔而動也剛。至靜而德方。後得主而有常。含萬物而化光。坤道其順乎。承天而時行。" aria-label="Permalink to “坤至柔而動也剛。至靜而德方。後得主而有常。含萬物而化光。坤道其順乎。承天而時行。”">​</a></h3><p>坤柔動剛。義與用六大終同。言坤雖至柔。遇六則變陽矣。故曰動剛。後得主而有常者。言最後變六為陽。以陽為主也。</p><h3 id="積善之家。必有餘慶。積不善之家。必有餘殃。臣弒其君。子弒其父。非一朝一夕之故。其所由來者漸矣。由辯之不早辯也。易曰。履霜堅冰至。蓋言順也。" tabindex="-1">積善之家。必有餘慶。積不善之家。必有餘殃。臣弒其君。子弒其父。非一朝一夕之故。其所由來者漸矣。由辯之不早辯也。易曰。履霜堅冰至。蓋言順也。 <a class="header-anchor" href="#積善之家。必有餘慶。積不善之家。必有餘殃。臣弒其君。子弒其父。非一朝一夕之故。其所由來者漸矣。由辯之不早辯也。易曰。履霜堅冰至。蓋言順也。" aria-label="Permalink to “積善之家。必有餘慶。積不善之家。必有餘殃。臣弒其君。子弒其父。非一朝一夕之故。其所由來者漸矣。由辯之不早辯也。易曰。履霜堅冰至。蓋言順也。”">​</a></h3><p>坤為積為殃為惡。故曰不善。坤多故曰餘。又為臣子為弒為夕。君父則指乾也。坤消陽故曰弒君父。此正申明履霜堅冰至之理。陰在姤至微耳。積之不已。則陽可全消。其禍有不可勝言者。故曰餘殃。餘者多也，此本世界之公理。人事之自然。而李鼎祚忽以夫子不語怪力亂神為疑。若餘慶餘殃。有類於神道感應之說者。真可謂汙衊聖言。不識語旨矣。漸孔疏雲。徐而不速謂之漸。辯說文判也。別也。謂宜別之於先也。順與循同義。蓋言順者。仍循其道則至堅冰之意。荀爽謂臣順君命而成之。背經旨。不可從。(文言釋初六噓吸經髓。超妙絕倫。使人惕然省。憬然悟。釋上六祇以陰凝陽天玄地黃。逗露坤地生物之本。由於天地交。而總不明言。仍還經文崑崙語氣。由此見聖人之言。寧使人不易知。而不能不文。太玄雲。不約則其旨不詳。不要則其應不博。不沈則其意不見。真能窺見載道之故者哉。)</p><h3 id="直其正也。方其義也。君子敬以直內。義以方外。敬義立而德不孤。直方大。不習無不利。則不疑其所行也。" tabindex="-1">直其正也。方其義也。君子敬以直內。義以方外。敬義立而德不孤。直方大。不習無不利。則不疑其所行也。 <a class="header-anchor" href="#直其正也。方其義也。君子敬以直內。義以方外。敬義立而德不孤。直方大。不習無不利。則不疑其所行也。" aria-label="Permalink to “直其正也。方其義也。君子敬以直內。義以方外。敬義立而德不孤。直方大。不習無不利。則不疑其所行也。”">​</a></h3><p>直則不撓。故曰直其正。言二中正也，方則不詭隨。放曰方其義。言不苟同也。正直髮於心。故曰直內。內直則必敬矣。故曰敬以直內。義方以接物。故曰方外。外方則無不宜矣。故曰義以方外。敬義之德立於下。五陽應於上。故德不孤。蓋陰消至二遁。前承重陽。二五應予。乾先坤後。陽唱陰和。得主有利。故不疑其所行。(舊解祇惠棟知以二五相應說不孤。最為卓識。)</p><h3 id="陰雖有美。含以之以從王事。弗敢成也。地道也。妻道也。臣道也。地道無成。而代有終也。" tabindex="-1">陰雖有美。含以之以從王事。弗敢成也。地道也。妻道也。臣道也。地道無成。而代有終也。 <a class="header-anchor" href="#陰雖有美。含以之以從王事。弗敢成也。地道也。妻道也。臣道也。地道無成。而代有終也。" aria-label="Permalink to “陰雖有美。含以之以從王事。弗敢成也。地道也。妻道也。臣道也。地道無成。而代有終也。”">​</a></h3><p>陽革於午。陰代陽用事。以訖於亥。故曰代有終。凡終皆謂亥。彖傳曰。乃終有慶。說卦曰萬物之所成終。終皆謂亥。內經與莊子。所謂天門者此也。自復子至乾巳皆成事。陽主之。故地道無成。自姤午至坤亥皆終事。陰主之。故曰代有終。言代陽終事也。終字從冬。言一年之事。至亥冬而終也。(子即陽復)故艮居亥而艮即為終。成者法也式也。周禮天官太宰。五曰官成以經邦治。注。官成謂官府之成事品式。又秋官士師掌士之八成。注。八成猶八法。然則成者法也。地道無成者。謂坤柔不敢先創為法式。只能代陽終事也。成與終虛實先後。絕對不同。漢宋衷以成名為說。清惠棟謂成與終同義。夫成與終義誠可通。但此曰無成。曰有終。則判然二事。不得混同也。</p><h3 id="天地變化。草木蕃-天地閉。賢人隱。易曰。括囊無咎無譽。蓋言謹也。" tabindex="-1">天地變化。草木蕃 天地閉。賢人隱。易曰。括囊無咎無譽。蓋言謹也。 <a class="header-anchor" href="#天地變化。草木蕃-天地閉。賢人隱。易曰。括囊無咎無譽。蓋言謹也。" aria-label="Permalink to “天地變化。草木蕃 天地閉。賢人隱。易曰。括囊無咎無譽。蓋言謹也。”">​</a></h3><p>陰消至四八月觀。由元亨而入利貞。天地之氣。將變易矣。觀下坤為茅茹為草。巽為木。坤閉艮止。故曰草木蕃。蕃與藩通。詩大雅四國於蕃是也。又周禮地官大司徒。九曰蕃樂。注。杜子春讀蕃樂為藩樂。謂閉藏樂器而不作。賈疏。藩謂藩閉。然則草木蕃者。言草木至八月而生氣藩閉也。自漢以來。無不以蕃息為解。豈知此與下天地閉賢人隱。平列為證。以釋括囊之義。若作蕃息。與括囊何涉乎。乾彖傳雲。乾道變化。各正性命。保合太和乃利貞。言元亨時過。利貞時至也。故曰變化。此變化與彼變化同也。變化之徵。在物則草木黃落。在天則陽氣閉藏。在人則賢哲隱遁。謹慎也。釋括囊之故也。</p><h3 id="君子黃中通理。正位居體。美在其中。而暢於四支。發於事業。美之至也。" tabindex="-1">君子黃中通理。正位居體。美在其中。而暢於四支。發於事業。美之至也。 <a class="header-anchor" href="#君子黃中通理。正位居體。美在其中。而暢於四支。發於事業。美之至也。" aria-label="Permalink to “君子黃中通理。正位居體。美在其中。而暢於四支。發於事業。美之至也。”">​</a></h3><p>地色黃。黃中色。五中位。故曰黃中。玉篇理文也。坤為文。故曰理。黃中通理者。言由中發外。有文理可見也。正位居體。即體居正位。坤為體為事業。言有黃中之德者。身必潤。事業必成也。</p><h3 id="陰凝於陽必戰。為其嫌於無陽也。故稱龍焉。猶未離其類也。故稱血焉。夫玄黃者。天地之雜也。天玄而地黃。" tabindex="-1">陰凝於陽必戰。為其嫌於無陽也。故稱龍焉。猶未離其類也。故稱血焉。夫玄黃者。天地之雜也。天玄而地黃。 <a class="header-anchor" href="#陰凝於陽必戰。為其嫌於無陽也。故稱龍焉。猶未離其類也。故稱血焉。夫玄黃者。天地之雜也。天玄而地黃。" aria-label="Permalink to “陰凝於陽必戰。為其嫌於無陽也。故稱龍焉。猶未離其類也。故稱血焉。夫玄黃者。天地之雜也。天玄而地黃。”">​</a></h3><p>凝王弼本作疑。釋文雲。荀虞姚信蜀才作凝。茲從其多者。然疑即凝字。莊子達生篇。用志不分。乃疑於神。即凝於神也。詩大雅靡所止疑。傳疑定也。正義音凝。可見疑凝本通。孟喜王弼詁作疑似之疑。致與經旨全背。夫陰陽相求相應。何疑忌之有。又何來戰爭。天地若至於戰爭。又胡由相雜。是皆由戰字失詁。不知相雜者為何義也。陰凝陽即陰牝陽。陰極於亥。與伏乾相遇。坤上乾上。坤外乾內。陽不見。故曰嫌於無陽。稱龍所以明有陽也。陰陽合為類。離則為獨陰獨陽。獨陰獨陽不能生。即不成為血。既曰血。即陰陽類也。即天地雜也。其血玄黃者。言此血非陰非陽。亦陰亦陽。為天地所和合。故能生萬物也。舊解不知陰陽合為類。又不知此言大地生物之本。故未離其類四句。舉不知其所謂。</p>',52)])])}const c=t(p,[["render",u]]);export{d as __pageData,c as default};
